import { chainPrivatePromise } from "../security/private-promise.js";
import { createPrivateAsyncLocalStorage } from "../security/private-async-context.js";
const credentialStorage = createPrivateAsyncLocalStorage();
const run = credentialStorage.run;
const getStore = credentialStorage.getStore;
const apply = Reflect.apply;
const freeze = Object.freeze;
/** @internal Bind a host-verified exact-run credential around trusted skill execution. */
export async function runWithVerifiedSkillScriptExecutionCredential(authority, operation) {
    authority.assertActive();
    let active = true;
    let operationSettled = false;
    let pendingProducers = 0;
    const revokeWhenSettled = () => {
        if (operationSettled && pendingProducers === 0)
            active = false;
    };
    const scopedAuthority = freeze({
        retain(completion) {
            if (operationSettled) {
                throw new TypeError("Skill script execution credential setup has ended");
            }
            if (!active)
                throw new TypeError("Skill script execution credential is no longer active");
            authority.assertActive();
            pendingProducers++;
            const settle = () => {
                pendingProducers--;
                revokeWhenSettled();
            };
            void chainPrivatePromise(completion, settle, settle);
        },
        assertActive() {
            if (!active)
                throw new TypeError("Skill script execution credential is no longer active");
            authority.assertActive();
        },
        read() {
            if (!active)
                throw new TypeError("Skill script execution credential is no longer active");
            authority.assertActive();
            return authority.read();
        },
    });
    try {
        return await apply(run, credentialStorage, [scopedAuthority, operation]);
    }
    finally {
        operationSettled = true;
        revokeWhenSettled();
    }
}
/** @internal Read the active credential only after its host authority remains live. */
export function getVerifiedSkillScriptExecutionCredential() {
    const authority = apply(getStore, credentialStorage, []);
    if (!authority)
        return undefined;
    authority.assertActive();
    return freeze({ ...authority.read() });
}
/** @internal Retain the current credential until an actual runtime producer settles. */
export function retainVerifiedSkillScriptExecutionCredentialUntil(completion) {
    const authority = apply(getStore, credentialStorage, []);
    authority?.retain(completion);
}
